import app from "./dist/worker/index.js";

async function runTests() {
  console.log("Starting API Tests...");
  let passed = 0;
  let failed = 0;

  const assert = (condition, message) => {
    if (condition) {
      passed++;
      console.log(`✅ PASS: ${message}`);
    } else {
      failed++;
      console.error(`❌ FAIL: ${message}`);
    }
  };

  const mockEnv = {
    ASSETS: {
      fetch: () => new Response("Asset"),
    },
  };
  const mockCf = {};

  // Test 1: GET /api/users (initial state, should be empty)
  {
    const req = new Request("http://localhost/api/users", { method: "GET" });
    const res = await app.fetch(req, mockEnv, mockCf);
    assert(res.status === 200, "GET /api/users status is 200");
    assert(res.headers.get("Content-Type") === "application/json", "GET /api/users Content-Type is application/json");
    const body = await res.json();
    assert(Array.isArray(body.users) && body.users.length === 0, "GET /api/users returns empty array initially");
  }

  // Test 2: POST /api/users (invalid payload - missing name/email)
  {
    const req = new Request("http://localhost/api/users", {
      method: "POST",
      body: JSON.stringify({ name: "John" }),
      headers: { "Content-Type": "application/json" },
    });
    const res = await app.fetch(req, mockEnv, mockCf);
    assert(res.status === 400, "POST /api/users missing email status is 400");
    const body = await res.json();
    assert(body.error === "invalid payload", "POST /api/users missing email returns error: invalid payload");
  }

  // Test 3: POST /api/users (invalid payload - wrong types)
  {
    const req = new Request("http://localhost/api/users", {
      method: "POST",
      body: JSON.stringify({ name: "John", email: 123 }),
      headers: { "Content-Type": "application/json" },
    });
    const res = await app.fetch(req, mockEnv, mockCf);
    assert(res.status === 400, "POST /api/users wrong email type status is 400");
    const body = await res.json();
    assert(body.error === "invalid payload", "POST /api/users wrong email type returns error: invalid payload");
  }

  // Test 4: POST /api/users (valid payload - user 1)
  let user1;
  {
    const req = new Request("http://localhost/api/users", {
      method: "POST",
      body: JSON.stringify({ name: "Alice", email: "alice@example.com" }),
      headers: { "Content-Type": "application/json" },
    });
    const res = await app.fetch(req, mockEnv, mockCf);
    assert(res.status === 201, "POST /api/users creates user status is 201");
    assert(res.headers.get("Content-Type") === "application/json", "POST /api/users Content-Type is application/json");
    user1 = await res.json();
    assert(typeof user1.id === "string" && user1.id.length > 0, "POST /api/users generates valid string ID");
    assert(user1.name === "Alice", "POST /api/users returns correct name");
    assert(user1.email === "alice@example.com", "POST /api/users returns correct email");
  }

  // Test 5: POST /api/users (valid payload - user 2)
  let user2;
  {
    const req = new Request("http://localhost/api/users", {
      method: "POST",
      body: JSON.stringify({ name: "Bob", email: "bob@example.com" }),
      headers: { "Content-Type": "application/json" },
    });
    const res = await app.fetch(req, mockEnv, mockCf);
    assert(res.status === 201, "POST /api/users creates user 2 status is 201");
    user2 = await res.json();
  }

  // Test 6: GET /api/users (should have two users in insertion order)
  {
    const req = new Request("http://localhost/api/users", { method: "GET" });
    const res = await app.fetch(req, mockEnv, mockCf);
    assert(res.status === 200, "GET /api/users status is 200");
    const body = await res.json();
    assert(body.users.length === 2, "GET /api/users returns 2 users");
    assert(body.users[0].id === user1.id, "First user is Alice (insertion order)");
    assert(body.users[1].id === user2.id, "Second user is Bob (insertion order)");
  }

  // Test 7: GET /api/users/:id (existing user)
  {
    const req = new Request(`http://localhost/api/users/${user1.id}`, { method: "GET" });
    const res = await app.fetch(req, mockEnv, mockCf);
    assert(res.status === 200, "GET /api/users/:id status is 200 for existing user");
    assert(res.headers.get("Content-Type") === "application/json", "GET /api/users/:id Content-Type is application/json");
    const body = await res.json();
    assert(body.id === user1.id && body.name === "Alice", "GET /api/users/:id returns correct user");
  }

  // Test 8: GET /api/users/:id (non-existing user)
  {
    const req = new Request("http://localhost/api/users/does-not-exist", { method: "GET" });
    const res = await app.fetch(req, mockEnv, mockCf);
    assert(res.status === 404, "GET /api/users/:id status is 404 for non-existing user");
    assert(res.headers.get("Content-Type") === "application/json", "GET /api/users/:id non-existing Content-Type is application/json");
    const body = await res.json();
    assert(body.error === "not found", "GET /api/users/:id non-existing returns error: not found");
  }

  // Test 9: PUT /api/users/:id (update existing user - name only)
  {
    const req = new Request(`http://localhost/api/users/${user1.id}`, {
      method: "PUT",
      body: JSON.stringify({ name: "Alice Updated" }),
      headers: { "Content-Type": "application/json" },
    });
    const res = await app.fetch(req, mockEnv, mockCf);
    assert(res.status === 200, "PUT /api/users/:id status is 200");
    assert(res.headers.get("Content-Type") === "application/json", "PUT /api/users/:id Content-Type is application/json");
    const body = await res.json();
    assert(body.id === user1.id && body.name === "Alice Updated" && body.email === "alice@example.com", "PUT /api/users/:id correctly updates name and keeps email");
  }

  // Test 10: PUT /api/users/:id (update existing user - email only)
  {
    const req = new Request(`http://localhost/api/users/${user1.id}`, {
      method: "PUT",
      body: JSON.stringify({ email: "alice.updated@example.com" }),
      headers: { "Content-Type": "application/json" },
    });
    const res = await app.fetch(req, mockEnv, mockCf);
    assert(res.status === 200, "PUT /api/users/:id email update status is 200");
    const body = await res.json();
    assert(body.id === user1.id && body.name === "Alice Updated" && body.email === "alice.updated@example.com", "PUT /api/users/:id correctly updates email and keeps name");
  }

  // Test 11: PUT /api/users/:id (update existing user - wrong types)
  {
    const req = new Request(`http://localhost/api/users/${user1.id}`, {
      method: "PUT",
      body: JSON.stringify({ name: 123 }),
      headers: { "Content-Type": "application/json" },
    });
    const res = await app.fetch(req, mockEnv, mockCf);
    assert(res.status === 400, "PUT /api/users/:id wrong type status is 400");
    const body = await res.json();
    assert(body.error === "invalid payload", "PUT /api/users/:id wrong type returns error: invalid payload");
  }

  // Test 12: PUT /api/users/:id (non-existing user)
  {
    const req = new Request("http://localhost/api/users/does-not-exist", {
      method: "PUT",
      body: JSON.stringify({ name: "Nobody" }),
      headers: { "Content-Type": "application/json" },
    });
    const res = await app.fetch(req, mockEnv, mockCf);
    assert(res.status === 404, "PUT /api/users/:id non-existing status is 404");
  }

  // Test 13: DELETE /api/users/:id (existing user)
  {
    const req = new Request(`http://localhost/api/users/${user1.id}`, { method: "DELETE" });
    const res = await app.fetch(req, mockEnv, mockCf);
    assert(res.status === 204, "DELETE /api/users/:id status is 204");
    assert(res.body === null || (await res.text()).length === 0, "DELETE /api/users/:id returns empty body");
  }

  // Test 14: GET /api/users/:id (deleted user should be 404)
  {
    const req = new Request(`http://localhost/api/users/${user1.id}`, { method: "GET" });
    const res = await app.fetch(req, mockEnv, mockCf);
    assert(res.status === 404, "GET /api/users/:id for deleted user status is 404");
  }

  // Test 15: DELETE /api/users/:id (non-existing user)
  {
    const req = new Request("http://localhost/api/users/does-not-exist", { method: "DELETE" });
    const res = await app.fetch(req, mockEnv, mockCf);
    assert(res.status === 404, "DELETE /api/users/:id non-existing status is 404");
    const body = await res.json();
    assert(body.error === "not found", "DELETE /api/users/:id non-existing returns error: not found");
  }

  console.log(`\nTests Summary: ${passed} passed, ${failed} failed.`);
  if (failed > 0) {
    process.exit(1);
  } else {
    console.log("🎉 All tests passed successfully!");
  }
}

runTests().catch((err) => {
  console.error("Test execution failed:", err);
  process.exit(1);
});

